package com.bank.dateformat;

import java.time.LocalDate;
import java.util.logging.*;

public class FormatterDemo {
    private static final Logger log = Logger.getLogger("DateFormat");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        DateFormatService service = new DateFormatService();
        String text = service.format(LocalDate.parse("2020-01-15"));
        log.info(() -> "Formatted joining date: " + text);
    }
}

// ─── Would be in service/DateFormatService.java ───
class DateFormatService {
    // shared, immutable, thread-safe; Locale fixed for deterministic month names
    private static final java.time.format.DateTimeFormatter FMT =
        java.time.format.DateTimeFormatter.ofPattern("dd-MMM-yyyy", java.util.Locale.ENGLISH);

    String format(LocalDate date) {
        return date.format(FMT);   // "15-Jan-2020"
    }
}
